#!/usr/bin/env python3
"""Stage 2a: merge ../results/fhe_*.csv into ../results/RESULTS.md."""
import csv, glob, os
R = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'results')
runs = []
for f in sorted(glob.glob(os.path.join(R, 'fhe_*.csv'))):
    lines = open(f).read().splitlines()
    hdr = lines[0].lstrip('# ')
    d = {(r['section'], r['item']): r['value'] for r in csv.DictReader(lines[1:])}
    runs.append((os.path.basename(f)[4:-4], hdr, d))
out = ['# BTHED Stage 2a results (two-key threshold RLWE layer, arithmetic core)', '',
       'Generated by `analyze.py`. One column per run; see the README for what is real and what is emulated.', '']
env = os.path.join(R, 'environment.txt')
if os.path.exists(env):
    out += ['**Environment.** ' + '; '.join(x.strip() for x in open(env) if x.strip()), '']
out += ['**Runs.**', ''] + [f'- `{n}`: {h}' for n, h, _ in runs] + ['']
def fmt(sec, v):
    x = float(v)
    if sec == 'size_bytes':
        return f'{x/1e6:.2f} MB' if x >= 1e6 else f'{x/1e3:.0f} KB'
    return f'{x:g}' if sec == 'correctness' else f'{x:.1f}'
titles = {'correctness': '1. Correctness', 'noise_log2': '2. Noise (log2 of the largest coefficient of m + t*e)',
          'size_bytes': '3. Sizes', 'time_ms': '4. One-time costs (ms)', 'time_ms_per_session': '5. Cost per session (ms, single core)'}
for sec, title in titles.items():
    items = [k[1] for k in runs[0][2] if k[0] == sec]
    out += [f'## {title}', '', '| item | ' + ' | '.join(n for n, _, _ in runs) + ' |', '|---|' + '---|' * len(runs)]
    for it in items:
        out.append(f'| {it} | ' + ' | '.join(fmt(sec, d.get((sec, it), 'nan')) for _, _, d in runs) + ' |')
    out.append('')
# ---------------------------------------------------------------- stage 2b
cmps = []
for f in sorted(glob.glob(os.path.join(R, 'cmp_*.csv')), key=lambda x: int(x.split('alpha')[1][:-4])):
    lines = open(f).read().splitlines()
    cmps.append((os.path.basename(f)[4:-4], lines[0].lstrip('# '), {(r['variant'], r['item']): r['value'] for r in csv.DictReader(lines[1:])}))
if cmps:
    out += ['# BTHED Stage 2b results (one homomorphic comparison, CKKS, single key vs two keys)', '', '**Runs.**', ''] + [f'- `{n}`: {h}' for n, h, _ in cmps] + ['']
    rows = [('cleartext', 'max_error_of_the_polynomial_vs_sign'), ('single_key', 'levels_consumed'), ('single_key', 'ciphertext_multiplications'),
            ('single_key', 'wrong_signs_out_of_16384'), ('two_key', 'wrong_signs_out_of_16384'),
            ('single_key', 'max_error_vs_cleartext_polynomial_log2'), ('two_key', 'max_error_vs_cleartext_polynomial_log2'),
            ('single_key', 'time_comparison_total_ms'), ('two_key', 'time_comparison_total_ms'),
            ('single_key', 'time_per_comparison_amortized_us'), ('two_key', 'time_per_comparison_amortized_us'),
            ('ratio', 'two_key_over_single_key_one_multiplication'), ('ratio', 'two_key_over_single_key_comparison'),
            ('single_key', 'ciphertext_top_level_bytes'), ('two_key', 'ciphertext_top_level_bytes'),
            ('single_key', 'evaluation_key_bytes'), ('two_key', 'evaluation_key_bytes')]
    out += ['| variant | item | ' + ' | '.join(n for n, _, _ in cmps) + ' |', '|---|---|' + '---|' * len(cmps)]
    for v, it in rows:
        cells = []
        for _, _, d in cmps:
            x = float(d.get((v, it), 'nan'))
            cells.append(f'{x/1e6:.1f} MB' if it.endswith('bytes') else (f'{x:.3g}' if abs(x) < 100 else f'{x:.0f}'))
        out.append(f'| {v} | {it} | ' + ' | '.join(cells) + ' |')
    out += ['', 'The two-key evaluation key is per party (b, d0, d1, d2).', '']
open(os.path.join(R, 'RESULTS.md'), 'w').write('\n'.join(out) + '\n')
print('\n'.join(out))
